const touchPersonSecret = `-- name: TouchPersonSecret :exec
UPDATE person_secrets SET last_used_at = now()
WHERE id = $1 AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')
`

// Updated at most once a minute.
func (q *Queries) TouchPersonSecret(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, touchPersonSecret, id)
	return err
}

const trimOpenSecretRequests = `-- name: TrimOpenSecretRequests :execrows
DELETE FROM secret_requests
WHERE id_digest IN (
    SELECT r.id_digest FROM secret_requests r
    WHERE r.user_id = $1 AND r.used_at IS NULL AND r.expires_at > now()
    ORDER BY r.created_at DESC, r.id_digest
    OFFSET $2::int
)
`

type TrimOpenSecretRequestsParams struct {
	UserID uuid.UUID
	Keep   int32
}

// Keeps a person's newest keep open requests; older open ones are dropped.
func (q *Queries) TrimOpenSecretRequests(ctx context.Context, arg TrimOpenSecretRequestsParams) (int64, error) {
	result, err := q.db.Exec(ctx, trimOpenSecretRequests, arg.UserID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
